import json
traj=json.load(open('traj458.json'))
prev=None
for s in traj['steps']:
    if s.get('source')!='agent': continue
    sid=s['step_id']
    tcs=s.get('tool_calls',[]) or []
    for tc in tcs:
        name=tc.get('function_name'); args=tc.get('arguments',{})
        # signature
        if name=='browser': sig=('browser',args.get('action'),args.get('kind'))
        elif name=='exec': sig=('exec',(args.get('command','')[:40]))
        else: sig=(name,str(args)[:40])
        if sig!=prev:
            print(sid, name, '|', str(args)[:120])
            prev=sig
